fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2);
        host::display::state_set(2, h / 2);
        host::display::state_set(3, 3);
        host::display::state_set(4, 2);
        host::display::state_set(5, 0);
        host::display::state_set(6, 3);
        host::display::state_set(7, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    if host::display::state_get(7) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(120, 180, "OUT OF BALLS", 0xff4040, 4);
        host::display::draw_string(130, 250, "RALLY", 0x808080, 2);
        host::display::draw_number(250, 244, host::display::state_get(5), 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO SERVE", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut bx: i32 = host::display::state_get(1);
        let mut by: i32 = host::display::state_get(2);
        let mut vx: i32 = host::display::state_get(3);
        let mut vy: i32 = host::display::state_get(4);
        let mut py: i32 = host::display::pointer_y() - 35;
        if py < 0 { py = 0; }
        if py > h - 70 { py = h - 70; }
        bx = bx + vx;
        by = by + vy;
        if bx < 0 { bx = 0; vx = -vx; }
        if by < 0 { by = 0; vy = -vy; }
        if by > h - 10 { by = h - 10; vy = -vy; }
        if bx > w - 26 && bx < w - 12 && vx > 0 && by + 10 > py && by < py + 70 {
            bx = w - 26;
            vx = -vx;
            let hits: i32 = host::display::state_get(5) + 1;
            host::display::state_set(5, hits);
            if hits % 5 == 0 {
                let mut mag: i32 = vx;
                if mag < 0 { mag = -mag; }
                if mag < 9 {
                    if vx > 0 { vx = vx + 1; } else { vx = vx - 1; }
                }
            }
        }
        if bx > w {
            let lives: i32 = host::display::state_get(6) - 1;
            host::display::state_set(6, lives);
            if lives <= 0 { host::display::state_set(7, 1); }
            bx = w / 3;
            by = h / 3;
            vx = 3;
            vy = 2;
        }
        host::display::state_set(1, bx);
        host::display::state_set(2, by);
        host::display::state_set(3, vx);
        host::display::state_set(4, vy);
        host::display::clear(0x000000);
        host::display::fill_rect(0, 0, 4, h, 0x404040);
        host::display::fill_rect(w - 16, py, 8, 70, 0xffffff);
        host::display::fill_rect(bx, by, 10, 10, 0x00ff88);
        host::display::draw_string(8, 10, "RALLY", 0x808080, 2);
        host::display::draw_number(110, 10, host::display::state_get(5), 0xffffff, 2);
        let mut lf: i32 = 0;
        while lf < host::display::state_get(6) {
            host::display::fill_rect(w - 30 - lf * 18, 10, 12, 12, 0x00ff88);
            lf = lf + 1;
        }
    }
    host::display::present();
}
